SELECT e.*, d.name AS department_name, des.name AS designation_name, b.name AS branch_name
FROM employees e
LEFT JOIN departments d ON d.id = e.department_id
LEFT JOIN designations des ON des.id = e.designation_id
LEFT JOIN branches b ON b.id = e.branch_id
WHERE e.company_id = #{companyId}

    AND (
        LOWER(e.first_name || ' ' || e.last_name) LIKE LOWER(CONCAT('%', #{query}, '%'))
        OR LOWER(e.work_email) LIKE LOWER(CONCAT('%', #{query}, '%'))
        OR LOWER(e.employee_code) LIKE LOWER(CONCAT('%', #{query}, '%'))
    )


    AND e.department_id = #{departmentId}


    AND e.status = #{status}

ORDER BY e.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(e.id)
FROM employees e
WHERE e.company_id = #{companyId}

    AND (
        LOWER(e.first_name || ' ' || e.last_name) LIKE LOWER(CONCAT('%', #{query}, '%'))
        OR LOWER(e.work_email) LIKE LOWER(CONCAT('%', #{query}, '%'))
        OR LOWER(e.employee_code) LIKE LOWER(CONCAT('%', #{query}, '%'))
    )


    AND e.department_id = #{departmentId}


    AND e.status = #{status}

